import assert from 'node:assert/strict';
const state = `const status = {ok:true,status:'open',title:'build(mobile): 升级 Expo SDK 并适配原生依赖',checks:{total:21,passed:11,pending:9,failed:0,skipped:1},unresolvedCount:0,conflicts:false}; const statuses = new Map([['github:github.com/makecindy/cindy#9261',status]]);`;
export default {
  name: 'pr-popover',
  entry: './fixture.tsx',
  viewport: { width: 920, height: 850 },
  real: 'GitContextBadge, task card lookup, GhostCardPreview and sandbox action bridge',
  notCovered:
    'Scheduler and real provider execution; HTML is generated by the GitHub plugin and sanitized; host responses are simulated',
  stubs: {
    'src/renderer/contexts/AuthContext': {
      partial: `export const useAuth=()=>({dataOwnerId:'fixture'});`,
    },
    'src/renderer/hooks/useSessionGitContext':
      state +
      `export const useSessionGitContext=()=>({head:null,branchSource:null,prRefs:[{id:'ref',sessionId:'pr-task',owner:'makecindy',repo:'cindy',prNumber:9261}],prStatuses:statuses});`,
    'src/renderer/contexts/PrRefsContext':
      state +
      `export const usePrStatuses=()=>({statuses}); export const useTaskPrArchiveEligibility=()=>({eligible:false}); export const usePrActions=()=>({});`,
  },
  cases: {
    default: { about: 'Compact PR footer and separate settings with real plugin HTML' },
    idle: {
      about: 'Following, pointer outside the follow row',
      data: { stopAfter: 'following-idle' },
    },
    hover: { about: 'Following, pointer over the follow row', data: { stopAfter: 'following' } },
    settings: { about: 'Separate PR settings dialog', data: { stopAfter: 'settings' } },
    uninstalled: { about: 'Historical PR card remains but its plugin is uninstalled' },
  },
  async ready(page) {
    await page.locator('[data-pr-chip]').hover();
    await page.locator('[data-pr-manage]').waitFor();
    if ((await page.evaluate(() => window.__uiPage.ctx.case)) !== 'uninstalled')
      await page.frameLocator('iframe').locator('[data-ghost-action="pr:follow"]').waitFor();
  },
  async check(page, ui) {
    if ((await page.evaluate(() => window.__uiPage.ctx.case)) === 'uninstalled') {
      assert.equal(await page.locator('iframe').count(), 0);
      await ui.capture('uninstalled');
      await page.locator('[data-pr-manage]').click();
      await page.locator('#pr-url-pr-task').waitFor();
      await page.getByRole('button', { name: await ui.t('common.dismiss'), exact: true }).click();
      await page.mouse.move(800, 800);
      await page.locator('[data-pr-chip]').hover();
      await page.locator('[data-pr-manage]').waitFor();
      return;
    }
    const frame = page.frameLocator('iframe');
    const act = (id) => frame.locator(`[data-ghost-action="${id}"]`);
    const menu = async () => {
      await page.locator('[data-pr-manage]').click();
    };
    await ui.capture('not-following');
    await act('pr:follow').click();
    await frame.locator('[data-ghost-live-label]').waitFor();
    const waitForStopOpacity = (opacity) =>
      page.waitForFunction((value) => {
        const doc = document.querySelector('iframe')?.contentDocument;
        const button = doc?.querySelector('[data-ghost-action="pr:stop"]');
        return button && window.getComputedStyle(button).opacity === String(value);
      }, opacity);
    // Moving onto the title keeps the popover open but leaves the follow row.
    await page.getByText(await ui.t('ccAgent.gitContext.pr.checks'), { exact: true }).hover();
    await waitForStopOpacity(0);
    const row = page.locator('iframe');
    const restingBox = await row.boundingBox();
    await ui.capture('following-idle');
    if (ui.data.stopAfter === 'following-idle') return;
    await frame.locator('[data-ghost-live-label]').hover();
    await waitForStopOpacity(1);
    assert.deepEqual(await row.boundingBox(), restingBox);
    await ui.capture('following');
    if (ui.data.stopAfter === 'following') return;
    await page.getByText(await ui.t('ccAgent.gitContext.pr.checks'), { exact: true }).hover();
    await waitForStopOpacity(0);
    // Tab into the iframe from the existing gear: hiding must not remove the action from keyboard navigation.
    await page.locator('[data-pr-manage]').focus();
    await page.keyboard.press('Tab');
    await waitForStopOpacity(1);
    assert.equal(
      await page
        .locator('iframe')
        .evaluate(
          (el) => el.contentDocument.activeElement?.getAttribute('data-ghost-action') === 'pr:stop',
        ),
      true,
    );
    await ui.capture('following-keyboard');
    await act('pr:stop').click();
    await act('pr:follow').waitFor();
    await ui.capture('stopped');
    await menu();
    await ui.capture('settings-menu');
    await page.getByRole('menuitem', { name: 'PR 设置', exact: true }).click();
    await act('prset:rename').waitFor();
    await ui.capture('settings', { locator: page.locator('[role=dialog]') });
    if (ui.data.stopAfter === 'settings') return;
    await act('prset:archive').click();
    await act('prset:archive').waitFor();
    await ui.capture('settings-toggled', { locator: page.locator('[role=dialog]') });
    await act('prset:model').click();
    await act('prset:modelPick').waitFor();
    await ui.capture('custom-model', { locator: page.locator('[role=dialog]') });
    await act('prset:modelPick').click();
    await page
      .getByRole('listbox', { name: await ui.t('newChat.modelSelector.modelListAria') })
      .waitFor();
    await page.getByText('演示模型 B', { exact: true }).first().waitFor();
    await ui.capture('model-picker');
    await ui.capture('model-picker-panel', {
      locator: page.locator('[data-radix-popper-content-wrapper]').last(),
    });
    await page.getByText('演示模型 B', { exact: true }).first().click();
    await frame.getByText('演示模型 B · 示例供应商', { exact: true }).waitFor();
    await ui.capture('model-selected', { locator: page.locator('[role=dialog]') });
    await page.getByRole('button', { name: await ui.t('common.dismiss'), exact: true }).click();
    await page.mouse.move(800, 800);
    await page.locator('[data-pr-chip]').hover();
    await page.locator('[data-pr-manage]').waitFor();
    await menu();
    await page.getByRole('menuitem', { name: 'PR 设置', exact: true }).click();
    await frame.getByText('演示模型 B · 示例供应商', { exact: true }).waitFor();
    await act('prset:model').press('Escape');
    await page.locator('iframe').waitFor({ state: 'detached' });
    await page.mouse.move(800, 800);
    await page.locator('[data-pr-chip]').hover();
    await page.locator('[data-pr-manage]').waitFor();
    await menu();
    await page
      .getByRole('menuitem', {
        name: await ui.t('ccAgent.gitContext.pr.manage.title'),
        exact: true,
      })
      .click();
    await page.locator('#pr-url-pr-task').waitFor();
    await ui.capture('manage');
    await page
      .getByRole('button', { name: await ui.t('ccAgent.gitContext.pr.manage.pin'), exact: true })
      .click();
    await ui.capture('pinned');
    await page
      .getByRole('button', { name: await ui.t('ccAgent.gitContext.pr.manage.remove'), exact: true })
      .last()
      .click();
    await page.locator('summary').click();
    await page
      .getByRole('button', {
        name: await ui.t('ccAgent.gitContext.pr.manage.restore'),
        exact: true,
      })
      .waitFor();
    await ui.capture('removed');
    await page
      .getByRole('button', {
        name: await ui.t('ccAgent.gitContext.pr.manage.restore'),
        exact: true,
      })
      .click();
    await ui.capture('restored');
  },
};
